const requestTypes = [
  ["Compra", "Aquisições e fornecedores", CreditCard],
  ["Pagamento", "Contas e reembolsos", WalletCards],
  ["Contratação", "Novas pessoas na equipe", UserRound],
  ["Documento", "Crie um documento", FileText],
  ["Manutenção", "Predial e equipamentos", Wrench],
  ["Acesso ou permissão", "Sistemas e ferramentas", LockKeyhole],
  ["Jurídico", "Contratos e pareceres", ShieldCheck],
  ["TI", "Infraestrutura e suporte", Command],
  ["Outra solicitação", "Comece do seu jeito", MoreHorizontal],
] as const;

function cn(...classes: (string | false | null | undefined)[]) {
  return classes.filter(Boolean).join(" ");
}

function Button({ children, variant = "primary", className, onClick, type = "button", disabled }: { children: React.ReactNode; variant?: "primary" | "secondary" | "ghost" | "danger" | "soft"; className?: string; onClick?: () => void; type?: "button" | "submit"; disabled?: boolean }) {
  const styles = {
    primary: "bg-[#157f7c] text-white shadow-sm hover:bg-[#0e6b69]",
    secondary: "border border-[#dce6e8] bg-white text-[#34444c] hover:border-[#b8cdcf] hover:bg-[#fbfdfd]",
    ghost: "text-[#64757d] hover:bg-[#f1f6f6] hover:text-[#17242c]",
    danger: "border border-[#f2d2ca] bg-[#fff8f6] text-[#c45c47] hover:bg-[#fff0ec]",
    soft: "bg-[#eaf8f7] text-[#0f7976] hover:bg-[#d9f2f1]",
  };
  return <button type={type} disabled={disabled} onClick={onClick} className={cn("inline-flex h-10 items-center justify-center gap-2 rounded-[10px] px-4 text-[13px] font-semibold transition disabled:cursor-not-allowed disabled:opacity-50", styles[variant], className)}>{children}</button>;
}

function Avatar({ initials, tone = "teal", size = "md" }: { initials: string; tone?: string; size?: "sm" | "md" | "lg" }) {
  const tones: Record<string, string> = { teal: "bg-[#d6f1ef] text-[#087672]", violet: "bg-[#e9e4ff] text-[#6655ad]", amber: "bg-[#fff0cf] text-[#a36d12]", rose: "bg-[#ffe1e3] text-[#b45667]", sky: "bg-[#dceeff] text-[#3e78ae]", orange: "bg-[#ffe5d4] text-[#ae6734]" };
  const sizes = { sm: "h-7 w-7 text-[10px]", md: "h-9 w-9 text-[11px]", lg: "h-11 w-11 text-[12px]" };
  return <div className={cn("flex shrink-0 items-center justify-center rounded-full font-bold", tones[tone] || tones.teal, sizes[size])}>{initials}</div>;
}

function Badge({ children, tone = "neutral" }: { children: React.ReactNode; tone?: "neutral" | "teal" | "amber" | "coral" | "green" | "blue" }) {
  const tones = { neutral: "bg-[#f2f5f5] text-[#627179]", teal: "bg-[#e4f7f5] text-[#0d807a]", amber: "bg-[#fff3d9] text-[#a8731d]", coral: "bg-[#fff0eb] text-[#c2634f]", green: "bg-[#e7f7eb] text-[#34804c]", blue: "bg-[#e9f1ff] text-[#4b72a9]" };
  return <span className={cn("inline-flex items-center rounded-md px-2 py-1 text-[11px] font-semibold", tones[tone])}>{children}</span>;
}

function Panel({ children, className = "", title, action }: { children: React.ReactNode; className?: string; title?: string; action?: React.ReactNode }) {
  return <section className={cn("rounded-2xl border border-[#e5edef] bg-white shadow-card", className)}>{title && <div className="flex items-center justify-between border-b border-[#eef2f2] px-5 py-4"><h2 className="font-display text-[15px] font-bold text-[#23323a]">{title}</h2>{action}</div>}{children}</section>;
}

function PageHeader({ eyebrow, title, description, action, back }: { eyebrow?: string; title: string; description?: string; action?: React.ReactNode; back?: () => void }) {
  return <div className="mb-7 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div>{eyebrow && <div className="mb-2 text-[11px] font-bold uppercase tracking-[.14em] text-[#789096]">{eyebrow}</div>}<div className="flex items-center gap-3">{back && <button onClick={back} className="rounded-lg p-2 text-[#77878d] hover:bg-white hover:text-[#17242c]"><ArrowLeft size={18} /></button>}<h1 className="font-display text-[28px] font-bold tracking-[-.04em] text-[#192930] sm:text-[32px]">{title}</h1></div>{description && <p className="mt-2 max-w-2xl text-[13px] leading-6 text-[#73838a]">{description}</p>}</div>{action && <div className="flex shrink-0 items-center gap-2">{action}</div>}</div>;
}

function Timeline({ compact = false }: { compact?: boolean }) {
  const steps = [{ label: "Criado", done: true }, { label: "Gestor", done: true }, { label: "Financeiro", active: true }, { label: "Diretoria" }, { label: "Concluído" }];
  return <div className={cn("flex items-start", compact ? "w-full max-w-[480px]" : "w-full")}>
    {steps.map((step, index) => <div key={step.label} className="flex min-w-0 flex-1 items-start">
      <div className="relative flex min-w-0 flex-col items-center"><div className={cn("z-10 flex h-6 w-6 items-center justify-center rounded-full border-2", step.done ? "border-[#1aa5a1] bg-[#1aa5a1] text-white" : step.active ? "pulse-dot border-[#1aa5a1] bg-white text-[#1aa5a1]" : "border-[#dce5e6] bg-white text-[#c4ced0]")}>{step.done ? <Check size={13} strokeWidth={3} /> : step.active ? <span className="h-2 w-2 rounded-full bg-[#1aa5a1]" /> : <Circle size={8} fill="currentColor" />}</div><span className={cn("mt-2 whitespace-nowrap text-[10px] font-semibold", step.active ? "text-[#147d79]" : step.done ? "text-[#45575e]" : "text-[#a2afb3]")}>{step.label}</span></div>{index < steps.length - 1 && <div className={cn("mt-3 h-[2px] min-w-[18px] flex-1", steps[index + 1].done || step.done ? "bg-[#1aa5a1]" : step.active ? "bg-[#bce3e1]" : "bg-[#e6edef]")} />}</div>)}
  </div>;
}

function StatCard({ label, value, detail, icon: Icon, tone = "teal", emphasis = false }: { label: string; value: string; detail: string; icon: IconType; tone?: "teal" | "amber" | "coral" | "blue"; emphasis?: boolean }) {
  const tones = { teal: "bg-[#e8f8f6] text-[#0f807a]", amber: "bg-[#fff4dc] text-[#b27b21]", coral: "bg-[#fff0eb] text-[#c96551]", blue: "bg-[#eaf1ff] text-[#5c76a5]" };
  return <div className={cn("rounded-2xl border p-5 shadow-card", emphasis ? "border-[#bde4e1] bg-[#f2fcfb]" : "border-[#e5edef] bg-white")}><div className="flex items-start justify-between"><div className="text-[12px] font-semibold text-[#73838a]">{label}</div><div className={cn("flex h-8 w-8 items-center justify-center rounded-lg", tones[tone])}><Icon size={16} /></div></div><div className="mt-4 font-display text-[27px] font-bold tracking-[-.04em] text-[#1d3037]">{value}</div><div className={cn("mt-1 text-[11px] font-medium", emphasis ? "text-[#0f807a]" : "text-[#7c8b91]")}>{detail}</div></div>;
}

export function AppShell() {
  const pathname = usePathname();
  const [collapsed, setCollapsed] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);
  const section = pathname.split("/").filter(Boolean)[0] || "inicio";
  const navigate = (href: string) => { setMobileOpen(false); window.location.assign(href); };
  const isEditor = pathname.includes("/editor");
  const isDetail = pathname.startsWith("/solicitacoes/") && !pathname.endsWith("/nova");

  if (isEditor) return <EditorPage navigate={navigate} />;

  return <div className="min-h-screen bg-[#f6f9f9]">
    <Sidebar collapsed={collapsed} mobileOpen={mobileOpen} pathname={pathname} navigate={navigate} onToggle={() => setCollapsed(!collapsed)} />
    <div className={cn("main-shell min-h-screen transition-[margin] duration-200", collapsed ? "ml-[76px]" : "ml-[252px]")}>
      <Topbar onMenu={() => setMobileOpen(true)} section={isDetail ? "Solicitação" : section} navigate={navigate} />
      <main className="mx-auto max-w-[1440px] px-5 py-7 sm:px-8 lg:px-10">
        <div className="fade-in">
          {section === "inicio" && <Dashboard navigate={navigate} />}
          {section === "solicitacoes" && (isDetail ? <RequestDetail navigate={navigate} pathname={pathname} /> : pathname.endsWith("/nova") ? <NewRequest navigate={navigate} /> : <RequestsPage navigate={navigate} />)}
          {section === "documentos" && <DocumentsPage navigate={navigate} />}
          {section === "minha-caixa" && <InboxPage navigate={navigate} />}
          {section === "processos" && <ProcessesPage navigate={navigate} />}
          {section === "analytics" && <AnalyticsPage />}
          {section === "equipe" && <TeamPage />}
          {section === "modelos" && <TemplatesPage navigate={navigate} />}
          {section === "automacoes" && <AutomationsPage />}
          {section === "administracao" && <AdminPage />}
        </div>
      </main>
    </div>
  </div>;
}

function Sidebar({ collapsed, mobileOpen, pathname, navigate, onToggle }: { collapsed: boolean; mobileOpen: boolean; pathname: string; navigate: (href: string) => void; onToggle: () => void }) {
  return <aside className={cn("desktop-sidebar sidebar-transition fixed bottom-0 left-0 top-0 z-30 flex w-[252px] flex-col border-r border-[#e4ebed] bg-white", collapsed && "w-[76px]", mobileOpen && "open")}>
    <div className={cn("flex h-[76px] items-center border-b border-[#edf1f1] px-5", collapsed ? "justify-center px-0" : "justify-between")}>
      <button onClick={() => navigate("/")} className="flex items-center gap-2.5"><span className="flex h-8 w-8 items-center justify-center rounded-[10px] bg-[#167f7b] text-white shadow-sm"><Sparkles size={16} fill="currentColor" /></span><span className="font-display text-[18px] font-bold tracking-[-.04em] text-[#173238] sidebar-label">JOEX</span></button>
      {!collapsed && <button onClick={onToggle} className="rounded-lg p-2 text-[#9ba9ad] hover:bg-[#f3f7f7] hover:text-[#53666d]" aria-label="Recolher menu"><PanelLeftClose size={17} /></button>}
    </div>
    <div className={cn("border-b border-[#edf1f1] px-3 py-4", collapsed && "px-2")}>
      <button className={cn("flex w-full items-center gap-3 rounded-xl border border-[#e5edef] bg-[#fbfdfd] px-3 py-2.5 text-left hover:border-[#c9dcdc]", collapsed && "justify-center border-0 bg-transparent px-1")}>
        <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-[#dff2f0] text-[11px] font-bold text-[#0e7773]">EA</div><div className="min-w-0 flex-1 org-copy"><div className="truncate text-[11px] font-bold text-[#34464d]">Empresa Exemplo S.A.</div><div className="mt-0.5 text-[10px] text-[#8a989d]">Plano Business</div></div>{!collapsed && <ChevronDown size={14} className="text-[#9aa8ad]" />}
      </button>
    </div>
    <nav className="scrollbar-thin flex-1 overflow-y-auto px-3 py-4">{navGroups.map((group, groupIndex) => <div key={group.label || groupIndex} className={cn(groupIndex > 0 && "mt-6 border-t border-[#edf1f1] pt-5")}>{group.label && <div className="mb-2 px-3 text-[10px] font-bold uppercase tracking-[.14em] text-[#a0adb0] sidebar-label">{group.label}</div>}{group.items.map((item) => { const active = item.href === "/" ? pathname === "/" : pathname.startsWith(item.href); const Icon = item.icon; return <a key={item.href} href={item.href} aria-label={item.label} className={cn("group mb-1 flex h-10 w-full items-center gap-3 rounded-[10px] px-3 text-left text-[13px] font-medium transition", active ? "bg-[#eaf8f7] text-[#0d7773]" : "text-[#6b7a81] hover:bg-[#f4f7f7] hover:text-[#25373e]", collapsed && "justify-center px-0")}><Icon size={17} strokeWidth={active ? 2.3 : 1.8} /><span className="sidebar-label flex-1">{item.label}</span>{item.badge && <span className={cn("rounded-md px-1.5 py-0.5 text-[10px] font-bold sidebar-label", active ? "bg-white text-[#15817d]" : "bg-[#f1f5f5] text-[#869499]")}>{item.badge}</span>}</a>; })}</div>)}</nav>
    <div className="border-t border-[#edf1f1] px-3 py-3"><button className={cn("mb-1 flex h-9 w-full items-center gap-3 rounded-[10px] px-3 text-left text-[12px] font-medium text-[#718087] hover:bg-[#f4f7f7]", collapsed && "justify-center px-0")}><CircleHelp size={16} /><span className="sidebar-label">Ajuda e suporte</span></button><button className={cn("flex w-full items-center gap-3 rounded-xl p-2 text-left hover:bg-[#f5f8f8]", collapsed && "justify-center px-0")}><Avatar initials="LM" size="sm" /><span className="user-copy min-w-0 flex-1"><span className="block truncate text-[12px] font-bold text-[#33454c]">Lucas Martins</span><span className="block truncate text-[10px] text-[#8c999e]">Administrador</span></span><MoreHorizontal size={15} className="user-copy text-[#a3afb2]" /></button></div>
    {collapsed && <button onClick={onToggle} className="absolute -right-3 top-[84px] flex h-6 w-6 items-center justify-center rounded-full border border-[#e3ebec] bg-white text-[#64767d] shadow-sm"><PanelLeftOpen size={13} /></button>}
  </aside>;
}

function Topbar({ onMenu, section, navigate }: { onMenu: () => void; section: string; navigate: (href: string) => void }) {
  const labels: Record<string, string> = { inicio: "Visão geral", solicitacoes: "Solicitações", documentos: "Documentos", "minha-caixa": "Minha Caixa", processos: "Processos", analytics: "Analytics", equipe: "Equipe", modelos: "Modelos", automacoes: "Automações", administracao: "Administração" };
  return <header className="sticky top-0 z-20 flex h-[76px] items-center justify-between border-b border-[#e4ebed] bg-[#f6f9f9]/95 px-5 backdrop-blur sm:px-8 lg:px-10"><div className="flex items-center gap-3"><button aria-label="Abrir menu" onClick={onMenu} className="rounded-lg p-2 text-[#62747a] hover:bg-white md:hidden"><Menu size={19} /></button><div className="hidden items-center gap-2 text-[11px] font-medium text-[#9aa8ac] sm:flex"><span>JOEX</span><ChevronRight size={13} /><span className="text-[#55676e]">{labels[section] || section}</span></div></div><div className="flex items-center gap-2 sm:gap-3"><button className="hidden h-9 items-center gap-2 rounded-lg border border-[#e3eaeb] bg-white px-3 text-[11px] text-[#8a999e] shadow-sm md:flex"><Search size={14} /><span>Buscar em tudo</span><kbd className="ml-3 rounded border border-[#e6ecec] bg-[#fafcfc] px-1.5 py-0.5 text-[9px] text-[#a5b0b3]">⌘ K</kbd></button><button className="relative rounded-lg p-2 text-[#73858b] hover:bg-white"><Bell size={18} /><span className="absolute right-1.5 top-1.5 h-1.5 w-1.5 rounded-full bg-[#e8795f] ring-2 ring-[#f6f9f9]" /></button><div className="hidden h-6 w-px bg-[#e2e9ea] sm:block" /><button onClick={() => navigate("/solicitacoes/nova")} className="flex h-9 items-center gap-1.5 rounded-lg bg-[#167f7b] px-3 text-[12px] font-bold text-white shadow-sm hover:bg-[#0e6b69]"><Plus size={15} /> <span className="hidden sm:inline">Nova solicitação</span><span className="sm:hidden">Novo</span></button></div></header>;
}

function Dashboard({ navigate }: { navigate: (href: string) => void }) {
  return <>
    <PageHeader eyebrow="Segunda-feira, 04 de outubro de 2026" title="Bom dia, Lucas." description="Veja o que precisa da sua atenção e como estão os processos da sua empresa." action={<><Button variant="secondary" onClick={() => navigate("/documentos/editor")}><FilePenLine size={15} /> Novo documento</Button><Button onClick={() => navigate("/solicitacoes/nova")}><Plus size={16} /> Nova solicitação</Button></>} />
    <div className="mb-8 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Aguardando minha ação" value="8" detail="3 próximas do prazo" icon={Inbox} tone="teal" /><StatCard label="Solicitações abertas" value="34" detail="6 atrasadas" icon={Activity} tone="amber" /><StatCard label="Tempo médio de conclusão" value="2,7 dias" detail="↓ 18% nos últimos 30 dias" icon={Clock3} tone="blue" /><StatCard label="Tempo médio de espera" value="1,9 dia" detail="70% do tempo total" icon={Clock3} tone="coral" emphasis /></div>
    <div className="grid gap-6 xl:grid-cols-[1.42fr_1fr]">
      <Panel title="Precisa da sua atenção" action={<button onClick={() => navigate("/minha-caixa")} className="flex items-center gap-1 text-[11px] font-bold text-[#13817d] hover:text-[#0c615e]">Ver minha caixa <ArrowRight size={13} /></button>}><div className="divide-y divide-[#eef2f2]">{attentionItems.map((item, index) => <AttentionRow key={item.title} item={item} index={index} navigate={navigate} />)}</div></Panel>
      <Panel title="Insight JOEX" className="overflow-hidden"><div className="relative flex h-full min-h-[242px] flex-col justify-between overflow-hidden p-5"><div className="absolute -right-8 -top-10 h-36 w-36 rounded-full bg-[#e8f8f6] opacity-80" /><div className="relative"><div className="mb-4 flex items-center gap-2"><span className="flex h-7 w-7 items-center justify-center rounded-lg bg-[#d9f3f0] text-[#0e7d78]"><Sparkles size={14} /></span><span className="text-[11px] font-bold uppercase tracking-[.1em] text-[#0e7d78]">Insight JOEX</span></div><p className="max-w-[310px] text-[15px] font-semibold leading-6 text-[#26383f]">94% das compras inferiores a R$ 5.000 foram aprovadas sem alterações nos últimos 6 meses.</p></div><div className="relative mt-6 border-t border-[#e6f0ef] pt-4 text-[12px] leading-5 text-[#6c7f84]">Permitir aprovação direta pelo gerente poderia reduzir aproximadamente <strong className="text-[#0f7975]">14 horas</strong> deste processo.</div></div></Panel>
    </div>
    <div className="mt-6"><Panel title="Processos em andamento" action={<button onClick={() => navigate("/processos")} className="flex items-center gap-1 text-[11px] font-bold text-[#13817d]">Ver todos <ArrowRight size={13} /></button>}><div className="p-5"><div className="mb-5 flex items-start justify-between gap-4"><div><h3 className="font-display text-[17px] font-bold text-[#26383e]">Compra de notebooks</h3><p className="mt-1 text-[12px] text-[#87959a]">JOEX-2026-00482 · Aquisição de equipamentos</p></div><Badge tone="teal"><span className="mr-1.5 h-1.5 w-1.5 rounded-full bg-[#1aa5a1]" /> Aguardando Financeiro</Badge></div><Timeline /><div className="mt-7 grid gap-4 border-t border-[#eef2f2] pt-5 sm:grid-cols-2 lg:grid-cols-4"><InfoMetric label="Próxima ação" value="Aprovação financeira" icon={ClipboardCheck} /><InfoMetric label="Responsável" value="Mariana Costa" icon={UserRound} /><InfoMetric label="Tempo nesta etapa" value="4h12" icon={Clock3} /><InfoMetric label="Previsão de conclusão" value="07 out · 16h" icon={CalendarDays} tone="teal" /></div><div className="mt-4 flex items-center gap-2 text-[11px] font-semibold text-[#3d8b55]"><CheckCircle2 size={14} /> Dentro do prazo</div></div></Panel></div>
  </>;
}

function AttentionRow({ item, index, navigate }: { item: typeof attentionItems[number]; index: number; navigate: (href: string) => void }) {
  const icons = [CreditCard, FileCheck2, UserRound]; const Icon = icons[index];
  return <div className="flex flex-col gap-4 px-5 py-5 sm:flex-row sm:items-center sm:justify-between"><div className="flex min-w-0 items-start gap-3"><div className={cn("mt-0.5 flex h-9 w-9 shrink-0 items-center justify-center rounded-lg", item.tone === "teal" ? "bg-[#e5f7f5] text-[#0e817a]" : item.tone === "amber" ? "bg-[#fff4dc] text-[#b17a1d]" : "bg-[#fff0eb] text-[#c96550]")}><Icon size={16} /></div><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><h3 className="truncate text-[13px] font-bold text-[#26383f]">{item.title}</h3><Badge tone={item.tone === "teal" ? "teal" : item.tone === "amber" ? "amber" : "coral"}>{item.action}</Badge></div><div className="mt-2 flex flex-wrap gap-x-3 gap-y-1 text-[11px] text-[#7f8d92]"><span>{item.type}</span><span className="text-[#cad2d4]">·</span><span>{item.requester}</span><span className="text-[#cad2d4]">·</span><span>{item.department}</span><span className="text-[#cad2d4]">·</span><span>{item.detail}</span></div><div className="mt-2 flex flex-wrap gap-x-4 text-[11px] text-[#88969b]"><span className="flex items-center gap-1"><Clock3 size={12} /> Esperando {item.waiting}</span><span className="flex items-center gap-1"><CalendarDays size={12} /> Prazo {item.due}</span></div></div></div><div className="flex shrink-0 items-center gap-2 sm:pl-4"><Button variant="secondary" className="h-8 px-3 text-[11px]" onClick={() => navigate("/solicitacoes/JOEX-2026-00482")}>{index === 1 ? "Revisar documento" : "Abrir"}</Button>{index === 0 && <><Button variant="soft" className="h-8 px-3 text-[11px]">Aprovar</Button><button className="hidden rounded-lg p-2 text-[#98a6aa] hover:bg-[#f4f7f7] sm:block"><MoreHorizontal size={16} /></button></>}</div></div>;
}

function InfoMetric({ label, value, icon: Icon, tone }: { label: string; value: string; icon: IconType; tone?: string }) {
  return <div className="flex gap-2.5"><div className={cn("mt-0.5 flex h-7 w-7 shrink-0 items-center justify-center rounded-md bg-[#f3f7f7] text-[#7a8b90]", tone === "teal" && "bg-[#e6f7f5] text-[#0e807b]")}><Icon size={13} /></div><div><div className="text-[10px] font-medium text-[#94a1a5]">{label}</div><div className="mt-1 text-[12px] font-bold text-[#3a4c53]">{value}</div></div></div>;
}

function RequestsPage({ navigate }: { navigate: (href: string) => void }) {
  const [filter, setFilter] = useState("Todas"); const [search, setSearch] = useState("");
  const filters = ["Todas", "Minhas", "Aguardando minha ação", "Atrasadas", "Concluídas"];
  const filtered = useMemo(() => requests.filter((request) => { const matchesFilter = filter === "Todas" || (filter === "Atrasadas" ? request.status === "Atrasado" : filter === "Concluídas" ? request.status === "Concluído" : filter === "Aguardando minha ação" ? request.id === "JOEX-2026-00482" : true); return matchesFilter && `${request.title} ${request.type} ${request.requester}`.toLowerCase().includes(search.toLowerCase()); }), [filter, search]);
  return <><PageHeader title="Solicitações" description="Crie, acompanhe e gerencie solicitações da sua organização." action={<Button onClick={() => navigate("/solicitacoes/nova")}><Plus size={16} /> Nova solicitação</Button>} /><div className="mb-5 flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between"><div className="flex max-w-full gap-1 overflow-x-auto rounded-xl border border-[#e5edef] bg-white p-1">{filters.map((item) => <button key={item} onClick={() => setFilter(item)} className={cn("whitespace-nowrap rounded-lg px-3 py-2 text-[11px] font-semibold transition", filter === item ? "bg-[#e8f7f5] text-[#0e7e79]" : "text-[#77868b] hover:bg-[#f4f7f7]")}>{item}{item === "Aguardando minha ação" && <span className="ml-1.5 rounded bg-white px-1 py-0.5 text-[9px]">8</span>}</button>)}</div><div className="flex gap-2"><div className="flex h-10 min-w-0 flex-1 items-center gap-2 rounded-[10px] border border-[#e5edef] bg-white px-3 text-[#94a2a6] shadow-sm lg:w-64"><Search size={15} /><input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Buscar solicitação" className="min-w-0 flex-1 bg-transparent text-[12px] text-[#34464d] outline-none placeholder:text-[#a0adb1]" /></div><Button variant="secondary" className="h-10 px-3"><Filter size={15} /> <span className="hidden sm:inline">Filtros</span></Button></div></div><Panel><div className="scrollbar-thin overflow-x-auto"><table className="w-full min-w-[900px] border-collapse text-left"><thead><tr className="border-b border-[#edf1f1] bg-[#fbfcfc] text-[10px] uppercase tracking-[.08em] text-[#89979c]"><th className="px-5 py-3 font-bold">Solicitação</th><th className="px-3 py-3 font-bold">Tipo</th><th className="px-3 py-3 font-bold">Solicitante</th><th className="px-3 py-3 font-bold">Etapa atual</th><th className="px-3 py-3 font-bold">Responsável atual</th><th className="px-3 py-3 font-bold">Esperando</th><th className="px-3 py-3 font-bold">Prazo</th><th className="px-3 py-3 font-bold">Status</th><th className="px-3 py-3"></th></tr></thead><tbody>{filtered.map((request) => <RequestTableRow key={request.id} request={request} navigate={navigate} />)}</tbody></table></div>{filtered.length === 0 && <div className="px-5 py-16 text-center text-[13px] text-[#829096]">Nenhuma solicitação encontrada para estes filtros.</div>}<div className="flex items-center justify-between border-t border-[#edf1f1] px-5 py-3 text-[11px] text-[#8c999e]"><span>Mostrando {filtered.length} de 34 solicitações</span><div className="flex gap-1"><button className="rounded-md border border-[#e2eaeb] p-1.5 text-[#b2bdc0]"><ArrowLeft size={13} /></button><button className="rounded-md border border-[#d9e8e7] bg-[#e9f7f5] px-2.5 py-1 text-[#147c77]">1</button><button className="rounded-md border border-[#e2eaeb] px-2.5 py-1">2</button><button className="rounded-md border border-[#e2eaeb] px-2.5 py-1">3</button><button className="rounded-md border border-[#e2eaeb] p-1.5"><ArrowRight size={13} /></button></div></div></Panel></>;
}

function RequestTableRow({ request, navigate }: { request: RequestItem; navigate: (href: string) => void }) {
  const statusTone = request.status === "Atrasado" ? "coral" : request.status === "Concluído" ? "green" : "teal";
  return <tr onClick={() => navigate(`/solicitacoes/${request.id}`)} className="cursor-pointer border-b border-[#f0f3f3] text-[12px] last:border-0 hover:bg-[#fbfdfd]"><td className="px-5 py-4"><div className="font-bold text-[#30434a]">{request.title}</div><div className="mt-1 text-[10px] text-[#9aa7ab]">{request.id}</div></td><td className="px-3 py-4 text-[#687980]">{request.type}</td><td className="px-3 py-4 text-[#53666d]">{request.requester}</td><td className="px-3 py-4"><span className="flex items-center gap-1.5 text-[#52666d]"><span className={cn("h-1.5 w-1.5 rounded-full", request.status === "Atrasado" ? "bg-[#e8795f]" : request.status === "Concluído" ? "bg-[#54a96b]" : "bg-[#1aa5a1]")} />{request.stage}</span></td><td className="px-3 py-4 text-[#53666d]">{request.owner}</td><td className="px-3 py-4 font-medium text-[#63757b]">{request.waiting}</td><td className={cn("px-3 py-4", request.status === "Atrasado" ? "font-semibold text-[#c66651]" : "text-[#63757b]")}>{request.due}</td><td className="px-3 py-4"><Badge tone={statusTone}>{request.status}</Badge></td><td className="px-3 py-4"><ChevronRight size={15} className="text-[#a8b4b7]" /></td></tr>;
}

function NewRequest({ navigate }: { navigate: (href: string) => void }) {
  const [selected, setSelected] = useState("Compra"); const [submitted, setSubmitted] = useState(false);
  if (submitted) return <div className="mx-auto max-w-[720px] py-12 text-center"><div className="mx-auto flex h-16 w-16 items-center justify-center rounded-full bg-[#dff5ed] text-[#258657]"><CheckCircle2 size={32} /></div><h1 className="mt-6 font-display text-[30px] font-bold tracking-[-.04em] text-[#1c3037]">Solicitação enviada!</h1><p className="mx-auto mt-3 max-w-md text-[14px] leading-6 text-[#718187]">Sua solicitação foi criada e encaminhada para o gestor responsável. Você poderá acompanhar cada etapa pela JOEX.</p><div className="mt-7 flex justify-center gap-2"><Button variant="secondary" onClick={() => navigate("/solicitacoes")}>Ver solicitações</Button><Button onClick={() => { setSubmitted(false); setSelected("Compra"); }}>Criar outra</Button></div></div>;
  return <><PageHeader back={() => navigate("/solicitacoes")} eyebrow="Nova solicitação" title="O que você precisa?" description="Escolha um tipo para começar. A JOEX vai sugerir o caminho mais rápido para resolver sua solicitação." /><div className="grid gap-6 xl:grid-cols-[1fr_340px]"><div><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{requestTypes.map(([name, helper, Icon]) => <button key={name} onClick={() => setSelected(name)} className={cn("flex items-start gap-3 rounded-2xl border bg-white p-4 text-left shadow-card transition", selected === name ? "border-[#8ed3cf] bg-[#f3fcfb] ring-2 ring-[#dff4f2]" : "border-[#e5edef] hover:border-[#c9dcdc]")}><span className={cn("flex h-9 w-9 shrink-0 items-center justify-center rounded-lg", selected === name ? "bg-[#d8f2ef] text-[#0b7c77]" : "bg-[#f1f5f5] text-[#829197]")}><Icon size={17} /></span><span><span className="block text-[13px] font-bold text-[#33464d]">{name}</span><span className="mt-1 block text-[10px] leading-4 text-[#91a0a4]">{helper}</span></span></button>)}</div><Panel className="mt-6"><div className="border-b border-[#edf1f1] px-5 py-4"><h2 className="font-display text-[16px] font-bold text-[#25383f]">Detalhes da solicitação</h2><p className="mt-1 text-[11px] text-[#89979b]">Preencha o essencial. Você poderá complementar depois.</p></div><div className="grid gap-4 p-5 sm:grid-cols-2"><Field label="Título" placeholder="Ex.: Compra de 15 notebooks" className="sm:col-span-2" /><Field label="Descrição" placeholder="Conte um pouco mais sobre o que você precisa..." textarea className="sm:col-span-2" /><Field label="Departamento solicitante" select options={["Tecnologia da Informação", "Compras", "Financeiro", "Pessoas"]} /><Field label="Valor estimado" placeholder="R$ 0,00" /><Field label="Fornecedor, se houver" placeholder="Nome do fornecedor" /><Field label="Centro de custo" placeholder="Ex.: TI-2026-01" /><Field label="Prioridade" select options={["Normal", "Alta", "Urgente"]} /><Field label="Prazo desejado" placeholder="dd/mm/aaaa" /><Field label="Anexos" placeholder="Adicione arquivos" icon={Paperclip} /><Field label="Observações" placeholder="Alguma informação adicional?" textarea className="sm:col-span-2" /></div><div className="flex flex-col-reverse gap-2 border-t border-[#edf1f1] px-5 py-4 sm:flex-row sm:justify-end"><Button variant="secondary" onClick={() => navigate("/solicitacoes")}>Cancelar</Button><Button onClick={() => setSubmitted(true)}><Send size={14} /> Enviar solicitação</Button></div></Panel></div><div><Panel className="sticky top-[98px] overflow-hidden"><div className="border-b border-[#edf1f1] px-5 py-4"><div className="flex items-center gap-2"><Workflow size={16} className="text-[#12807c]" /><h2 className="font-display text-[15px] font-bold text-[#25383f]">Caminho previsto</h2></div><p className="mt-1 text-[11px] leading-5 text-[#8a989c]">Com base no tipo de solicitação e no departamento.</p></div><div className="p-5"><div className="space-y-0">{["Você", "Gestor", "Financeiro", "Diretoria"].map((step, index) => <div key={step} className="flex items-center gap-3"><div className="flex flex-col items-center"><div className={cn("flex h-7 w-7 items-center justify-center rounded-full border text-[11px] font-bold", index === 0 ? "border-[#b8e2df] bg-[#e8f8f6] text-[#0f807a]" : "border-[#dfe8e9] bg-white text-[#93a1a5]")}>{index === 0 ? <Check size={13} /> : index + 1}</div>{index < 3 && <div className="h-7 w-px bg-[#dfe9e9]" />}</div><span className={cn("text-[12px] font-semibold", index === 0 ? "text-[#34474e]" : "text-[#87969b]")}>{step}</span></div>)}</div><div className="mt-6 rounded-xl bg-[#f4faf9] p-4"><div className="flex items-center gap-2 text-[11px] font-bold text-[#4f6b70]"><Clock3 size={14} className="text-[#16847f]" /> Previsão inicial</div><div className="mt-2 font-display text-[20px] font-bold tracking-[-.03em] text-[#1e4547]">Conclusão estimada em 1 dia e 7 horas</div></div></div></Panel></div></div></>;
}

function Field({ label, placeholder, textarea, select, options, className = "", icon: Icon }: { label: string; placeholder?: string; textarea?: boolean; select?: boolean; options?: string[]; className?: string; icon?: IconType }) {
  return <label className={cn("block", className)}><span className="mb-1.5 block text-[11px] font-bold text-[#52666d]">{label}</span>{textarea ? <textarea rows={3} placeholder={placeholder} className="w-full resize-none rounded-[10px] border border-[#dfe8e9] bg-white px-3 py-2.5 text-[12px] outline-none placeholder:text-[#aab5b8] focus:border-[#7ec8c4] focus:ring-2 focus:ring-[#e4f5f3]" /> : select ? <div className="relative"><select className="w-full appearance-none rounded-[10px] border border-[#dfe8e9] bg-white px-3 py-2.5 text-[12px] text-[#6c7d83] outline-none focus:border-[#7ec8c4]">{options?.map((option) => <option key={option}>{option}</option>)}</select><ChevronDown size={14} className="pointer-events-none absolute right-3 top-3 text-[#9aa7aa]" /></div> : <div className="relative">{Icon && <Icon size={14} className="absolute left-3 top-3 text-[#a2afb2]" />}<input placeholder={placeholder} className={cn("w-full rounded-[10px] border border-[#dfe8e9] bg-white px-3 py-2.5 text-[12px] outline-none placeholder:text-[#aab5b8] focus:border-[#7ec8c4] focus:ring-2 focus:ring-[#e4f5f3]", Icon && "pl-9")} /></div>}</label>;
}

function RequestDetail({ navigate, pathname }: { navigate: (href: string) => void; pathname: string }) {
  const request = requests.find((item) => pathname.includes(item.id)) || requests[0];
  return <><PageHeader back={() => navigate("/solicitacoes")} eyebrow={request.id} title={request.title} description="Solicitação de aquisição de equipamentos para a renovação do parque de máquinas." action={<><Button variant="secondary" onClick={() => navigate("/documentos/editor")}><FileText size={15} /> Documentos (2)</Button><Button variant="soft"><Send size={14} /> Enviar lembrete</Button></>} /><div className="mb-6 flex flex-wrap items-center justify-between gap-3 rounded-2xl border border-[#c9e8e5] bg-[#f1fbfa] px-5 py-4"><div className="flex items-center gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#daf3ef] text-[#0c7c77]"><Clock3 size={19} /></div><div><div className="text-[11px] font-bold uppercase tracking-[.08em] text-[#5d8586]">Status atual</div><div className="mt-1 flex items-center gap-2 text-[15px] font-bold text-[#176c6a]">Aguardando Financeiro <span className="h-1.5 w-1.5 rounded-full bg-[#1aa5a1]" /></div></div></div><div className="flex flex-wrap gap-6 text-right"><div><div className="text-[10px] text-[#7c9899]">Próxima ação</div><div className="mt-1 text-[12px] font-bold text-[#385c5e]">Aprovação financeira</div></div><div><div className="text-[10px] text-[#7c9899]">Responsável</div><div className="mt-1 text-[12px] font-bold text-[#385c5e]">Mariana Costa</div></div><div><div className="text-[10px] text-[#7c9899]">Prazo</div><div className="mt-1 text-[12px] font-bold text-[#385c5e]">Hoje às 17:00</div></div><div><div className="text-[10px] text-[#7c9899]">Esperando</div><div className="mt-1 text-[12px] font-bold text-[#c46a52]">4h12</div></div></div></div><div className="grid gap-6 xl:grid-cols-[1.5fr_.8fr]"><div className="space-y-6"><Panel title="Timeline do processo"><div className="p-5"><Timeline /><div className="mt-7 grid gap-3 sm:grid-cols-3">{[["Criado", "04 out · 09:14"], ["Gestor", "04 out · 10:02"], ["Financeiro", "Em andamento"]].map(([label, value], i) => <div key={label} className="rounded-xl bg-[#fafcfc] p-3"><div className="flex items-center gap-1.5 text-[10px] font-bold text-[#7f8e93]"><span className={cn("h-1.5 w-1.5 rounded-full", i === 2 ? "bg-[#1aa5a1]" : "bg-[#65b37a]")} />{label}</div><div className="mt-2 text-[11px] font-semibold text-[#40545b]">{value}</div></div>)}</div></div></Panel><Panel title="Detalhes"><div className="grid gap-y-5 p-5 sm:grid-cols-3"><Detail label="Solicitante" value="Carlos Mendes" /><Detail label="Departamento" value="Tecnologia da Informação" /><Detail label="Valor" value="R$ 48.500" /><Detail label="Prioridade" value="Alta" tone="coral" /><Detail label="Data de criação" value="04 out 2026, 09:14" /><Detail label="Prazo" value="Hoje, 17:00" /><div className="sm:col-span-3"><Detail label="Descrição" value={request.description} /></div></div></Panel><Panel title="Histórico"><div className="space-y-5 p-5">{[["09:14", "Solicitação criada por Carlos Mendes", "A solicitação foi criada"], ["09:16", "Encaminhada automaticamente para Roberto Almeida", "Fluxo iniciado"], ["10:02", "Aprovada pelo gestor", "Roberto Almeida aprovou esta etapa"], ["10:03", "Encaminhada ao Financeiro", "Aguardando Mariana Costa"]].map(([time, title, desc], index) => <div className="flex gap-3" key={time}><div className="flex w-12 shrink-0 flex-col items-end"><span className="text-[10px] font-bold text-[#718188]">{time}</span>{index < 3 && <div className="mt-2 h-8 w-px bg-[#e4ecec]" />}</div><div className="relative flex-1 pb-1"><span className={cn("absolute -left-[21px] top-0 h-2.5 w-2.5 rounded-full border-2 border-white", index === 3 ? "bg-[#1aa5a1]" : "bg-[#78bfa0]")} /><div className="text-[12px] font-semibold text-[#3a4d54]">{title}</div><div className="mt-1 text-[11px] text-[#8c999e]">{desc}</div></div></div>)}</div></Panel><Panel title="Comentários"><div className="p-5"><div className="flex gap-3"><Avatar initials="LM" size="sm" /><div className="flex-1"><textarea rows={2} placeholder="Adicionar comentário..." className="w-full resize-none rounded-xl border border-[#dfe8e9] px-3 py-2.5 text-[12px] outline-none placeholder:text-[#a6b2b5] focus:border-[#7ec8c4]" /><div className="mt-2 flex justify-between"><span className="text-[10px] text-[#a0adb0]">Use @ para mencionar alguém</span><Button className="h-8 px-3 text-[11px]">Comentar</Button></div></div></div></div></Panel></div><div className="space-y-6"><Panel><div className="p-5"><div className="mb-2 flex items-center gap-2 text-[11px] font-bold uppercase tracking-[.08em] text-[#799095]"><Gauge size={14} className="text-[#1aa5a1]" /> Previsão</div><div className="font-display text-[24px] font-bold tracking-[-.04em] text-[#23373e]">7 de outubro às 16h</div><p className="mt-2 text-[11px] leading-5 text-[#87969b]">Baseado no tempo médio deste fluxo.</p><div className="mt-4 flex items-center gap-2 rounded-lg bg-[#eff9f0] px-3 py-2 text-[11px] font-semibold text-[#408451]"><CheckCircle2 size={14} /> Dentro do prazo</div></div></Panel><Panel title="Ações"><div className="space-y-2 p-4"><Button className="w-full">Aprovar solicitação</Button><Button variant="secondary" className="w-full">Solicitar alteração</Button><Button variant="secondary" className="w-full">Delegar aprovação</Button><Button variant="danger" className="w-full">Rejeitar</Button></div></Panel><Panel title="Anexos"><div className="space-y-2 p-4"><button onClick={() => navigate("/documentos/editor")} className="flex w-full items-center gap-3 rounded-xl border border-[#edf1f1] p-3 text-left hover:bg-[#fafcfc]"><div className="flex h-8 w-8 items-center justify-center rounded-lg bg-[#fff0eb] text-[#c66751]"><FileText size={15} /></div><div className="min-w-0 flex-1"><div className="truncate text-[11px] font-bold text-[#44575e]">Cotação_notebooks.pdf</div><div className="mt-1 text-[10px] text-[#9aa7aa]">2,4 MB · PDF</div></div><ChevronRight size={14} className="text-[#a4b1b4]" /></button><button onClick={() => navigate("/documentos/editor")} className="flex w-full items-center gap-3 rounded-xl border border-[#edf1f1] p-3 text-left hover:bg-[#fafcfc]"><div className="flex h-8 w-8 items-center justify-center rounded-lg bg-[#eaf7f5] text-[#18827d]"><FileCheck2 size={15} /></div><div className="min-w-0 flex-1"><div className="truncate text-[11px] font-bold text-[#44575e]">Parecer_financeiro_024.docx</div><div className="mt-1 text-[10px] text-[#9aa7aa]">486 KB · DOCX</div></div><ChevronRight size={14} className="text-[#a4b1b4]" /></button></div></Panel></div></div></>;
}

function Detail({ label, value, tone }: { label: string; value: string; tone?: string }) { return <div><div className="text-[10px] font-semibold text-[#9aa6aa]">{label}</div><div className={cn("mt-1.5 text-[12px] font-bold text-[#40535a]", tone === "coral" && "text-[#c56550]")}>{value}</div></div>; }

function DocumentsPage({ navigate }: { navigate: (href: string) => void }) {
  return <><PageHeader title="Documentos" description="Crie, edite, envie e acompanhe documentos sem sair da JOEX." action={<Button onClick={() => navigate("/documentos/editor")}><Plus size={16} /> Novo documento</Button>} /><div className="mb-7 grid gap-4 sm:grid-cols-3"><DocSummary icon={FileText} value="18" label="Documentos ativos" tone="teal" /><DocSummary icon={FileCheck2} value="6" label="Aguardando aprovação" tone="amber" /><DocSummary icon={Clock3} value="2,4 dias" label="Tempo médio de revisão" tone="blue" /></div><Panel title="Todos os documentos" action={<div className="flex gap-2"><button className="rounded-lg p-2 text-[#7d8d92] hover:bg-[#f3f7f7]"><Filter size={15} /></button><button className="rounded-lg p-2 text-[#7d8d92] hover:bg-[#f3f7f7]"><MoreHorizontal size={16} /></button></div>}><div className="scrollbar-thin overflow-x-auto"><table className="w-full min-w-[780px] text-left"><thead><tr className="border-b border-[#edf1f1] bg-[#fbfcfc] text-[10px] uppercase tracking-[.08em] text-[#89979c]"><th className="px-5 py-3 font-bold">Documento</th><th className="px-3 py-3 font-bold">Tipo</th><th className="px-3 py-3 font-bold">Autor</th><th className="px-3 py-3 font-bold">Última alteração</th><th className="px-3 py-3 font-bold">Situação</th><th className="px-3 py-3 font-bold">Processo associado</th><th /></tr></thead><tbody>{documents.map((doc) => <tr key={doc.id} onClick={() => navigate("/documentos/editor")} className="cursor-pointer border-b border-[#f0f3f3] text-[12px] last:border-0 hover:bg-[#fbfdfd]"><td className="px-5 py-4"><div className="flex items-center gap-3"><div className="flex h-8 w-8 items-center justify-center rounded-lg bg-[#eaf7f5] text-[#16827e]"><FileText size={15} /></div><div><div className="font-bold text-[#34474e]">{doc.title}</div><div className="mt-1 text-[10px] text-[#a0acaf]">{doc.id}</div></div></div></td><td className="px-3 py-4 text-[#6d7d83]">{doc.type}</td><td className="px-3 py-4 text-[#56686e]">{doc.author}</td><td className="px-3 py-4 text-[#78878c]">{doc.updated}</td><td className="px-3 py-4"><Badge tone={doc.situation === "Concluído" || doc.situation === "Aprovado" ? "green" : doc.situation === "Aguardando assinatura" ? "amber" : "teal"}>{doc.situation}</Badge></td><td className="px-3 py-4 text-[#66777d]">{doc.process}</td><td className="px-3 py-4"><ChevronRight size={15} className="text-[#a8b4b7]" /></td></tr>)}</tbody></table></div></Panel><div className="mt-7"><div className="mb-4 flex items-center justify-between"><div><h2 className="font-display text-[17px] font-bold text-[#26383f]">Criar a partir de modelo</h2><p className="mt-1 text-[12px] text-[#8b999e]">Comece com uma estrutura pronta e economize tempo.</p></div><button onClick={() => navigate("/modelos")} className="text-[11px] font-bold text-[#147f7b]">Ver todos</button></div><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{["Memorando", "Ofício", "Parecer", "Documento em branco"].map((name, i) => <button key={name} onClick={() => navigate("/documentos/editor")} className="flex items-center gap-3 rounded-xl border border-[#e5edef] bg-white p-4 text-left shadow-card hover:border-[#bddbd8]"><div className={cn("flex h-9 w-9 items-center justify-center rounded-lg", i === 3 ? "bg-[#f3f5f5] text-[#7e8e93]" : "bg-[#e8f7f5] text-[#15817c]")}><FilePenLine size={16} /></div><div><div className="text-[12px] font-bold text-[#3d5057]">{name}</div><div className="mt-1 text-[10px] text-[#95a1a5]">Modelo JOEX</div></div></button>)}</div></div></>;
}

function DocSummary({ icon: Icon, value, label, tone }: { icon: IconType; value: string; label: string; tone: string }) { return <div className="flex items-center gap-3 rounded-2xl border border-[#e5edef] bg-white p-4 shadow-card"><div className={cn("flex h-9 w-9 items-center justify-center rounded-lg", tone === "teal" ? "bg-[#e6f7f5] text-[#13807b]" : tone === "amber" ? "bg-[#fff3db] text-[#b27818]" : "bg-[#eaf1ff] text-[#5f78aa]")}><Icon size={17} /></div><div><div className="font-display text-[20px] font-bold text-[#30434a]">{value}</div><div className="mt-0.5 text-[10px] text-[#869499]">{label}</div></div></div>; }

function EditorPage({ navigate }: { navigate: (href: string) => void }) {
  const [saved, setSaved] = useState(true); const [activeTool, setActiveTool] = useState("");
  const tools: [string, IconType][] = [["bold", Copy], ["italic", PenLine], ["underline", Tag], ["align", ListChecks], ["list", ListChecks], ["link", Link2], ["table", Table2]];
  return <div className="min-h-screen bg-[#f0f4f4]"><header className="sticky top-0 z-20 flex h-[68px] items-center justify-between border-b border-[#dfe7e8] bg-white px-5 sm:px-8"><div className="flex items-center gap-3"><button onClick={() => navigate("/documentos")} className="rounded-lg p-2 text-[#718187] hover:bg-[#f3f7f7]"><ArrowLeft size={18} /></button><div className="h-7 w-px bg-[#e4ebec]" /><div><div className="flex items-center gap-2"><span className="font-display text-[15px] font-bold text-[#263940]">Memorando interno nº 018/2026</span><span className={cn("rounded-md px-2 py-1 text-[10px] font-semibold", saved ? "bg-[#eaf7f5] text-[#318179]" : "bg-[#fff3d9] text-[#a27420]")}>{saved ? "Salvo" : "Salvando..."}</span></div><div className="mt-1 hidden text-[10px] text-[#99a5a8] sm:block">Editado por Lucas Martins · há 2 minutos</div></div></div><div className="flex items-center gap-2"><Button variant="secondary" className="hidden sm:inline-flex"><Share2 size={14} /> Compartilhar</Button><Button onClick={() => { setSaved(false); setTimeout(() => setSaved(true), 700); }}><Send size={14} /> Enviar para aprovação</Button></div></header><div className="border-b border-[#dfe7e8] bg-white px-5 py-2.5 sm:px-8"><div className="mx-auto flex max-w-[920px] items-center gap-1 overflow-x-auto"><select className="h-8 rounded-md border-0 bg-[#f5f7f7] px-2 text-[11px] font-medium text-[#5c6d73] outline-none"><option>Arial</option><option>Georgia</option><option>Inter</option></select><select className="h-8 rounded-md border-0 bg-[#f5f7f7] px-2 text-[11px] font-medium text-[#5c6d73] outline-none"><option>11</option><option>12</option><option>14</option><option>16</option></select><div className="mx-2 h-5 w-px bg-[#e5ebec]" />{tools.map(([name, Icon]) => <button key={name} onClick={() => setActiveTool(name)} className={cn("flex h-8 w-8 items-center justify-center rounded-md text-[#708188] hover:bg-[#f0f5f5]", activeTool === name && "bg-[#e1f4f2] text-[#0f7b77]")}><Icon size={15} /></button>)}<div className="mx-2 h-5 w-px bg-[#e5ebec]" /><button className="flex h-8 items-center gap-1 rounded-md px-2 text-[11px] text-[#708188] hover:bg-[#f0f5f5]"><Clock3 size={14} /> Histórico</button></div></div><main className="grid-paper flex justify-center px-4 py-8 sm:px-10"><article contentEditable suppressContentEditableWarning className="document-paper w-full max-w-[760px] rounded-sm bg-white px-10 py-14 outline-none sm:px-20 sm:py-20"><div className="mb-14 border-b-2 border-[#273a40] pb-3 text-[13px] font-bold tracking-[.12em] text-[#273a40]">JOEX · EMPRESA EXEMPLO S.A.</div><div className="space-y-5 text-[13px] leading-7 text-[#44565c]"><h1 className="mb-10 text-center text-[18px] font-bold tracking-[.08em] text-[#26383f]">MEMORANDO INTERNO Nº 018/2026</h1><div className="grid grid-cols-[70px_1fr] gap-y-1"><strong>De:</strong><span>Departamento de Tecnologia da Informação</span><strong>Para:</strong><span>Diretoria Administrativa</span><strong>Assunto:</strong><span>Aquisição de equipamentos de informática</span><strong>Data:</strong><span>04 de outubro de 2026</span></div><p className="mt-10">Prezados,</p><p>Considerando o plano de renovação do parque tecnológico da Empresa Exemplo S.A., encaminhamos para apreciação a solicitação de aquisição de 15 notebooks para atender às necessidades das equipes de Tecnologia da Informação e Operações.</p><p>Os equipamentos serão destinados prioritariamente à substituição de máquinas que atingiram o fim de sua vida útil, garantindo maior segurança, desempenho e continuidade das atividades.</p><p>O investimento estimado é de <strong>R$ 48.500,00</strong>, conforme cotação anexada ao processo <strong>JOEX-2026-00482</strong>. A aquisição encontra-se neste momento aguardando aprovação financeira.</p><p>Ficamos à disposição para os esclarecimentos necessários.</p><p className="mt-10">Atenciosamente,</p><div className="mt-12 border-t border-[#cfdadb] pt-3 text-[12px]"><strong>Lucas Martins</strong><br /><span>Diretor Administrativo</span></div></div></article></main></div>;
}

function InboxPage({ navigate }: { navigate: (href: string) => void }) {
  return <><PageHeader title="Minha Caixa" description="Tudo que depende de você, organizado por urgência e contexto." action={<Button variant="secondary"><Filter size={15} /> Filtrar</Button>} /><div className="mb-6 grid gap-4 sm:grid-cols-4"><InboxStat value="8" label="Precisa da sua ação" tone="teal" /><InboxStat value="3" label="Próximas do prazo" tone="amber" /><InboxStat value="5" label="Menções" tone="blue" /><InboxStat value="12" label="Atualizações" tone="neutral" /></div><div className="grid gap-6 xl:grid-cols-[1.2fr_.8fr]"><Panel title="Precisa da sua ação" action={<Badge tone="teal">8 itens</Badge>}><div className="divide-y divide-[#eef2f2]">{[{ title: "Compra de 15 notebooks", sub: "Aprovação financeira · Carlos Mendes", due: "Hoje, 17:00", waiting: "4h12", icon: CreditCard, tone: "teal" }, { title: "Parecer financeiro nº 024/2026", sub: "Assinatura da Diretoria · Mariana Costa", due: "Hoje, 18:30", waiting: "2h40", icon: FileCheck2, tone: "amber" }, { title: "Contrato fornecedor Alpha", sub: "Revisão necessária · Marina Souza", due: "Amanhã", waiting: "1d 3h", icon: FileText, tone: "blue" }].map((item) => <button key={item.title} onClick={() => navigate(item.title.includes("Compra") ? "/solicitacoes/JOEX-2026-00482" : "/documentos/editor")} className="flex w-full items-center gap-3 px-5 py-4 text-left hover:bg-[#fbfdfd]"><div className={cn("flex h-9 w-9 shrink-0 items-center justify-center rounded-lg", item.tone === "teal" ? "bg-[#e5f7f5] text-[#0e817a]" : item.tone === "amber" ? "bg-[#fff3db] text-[#b3791d]" : "bg-[#eaf1ff] text-[#5f79a9]")}><item.icon size={16} /></div><div className="min-w-0 flex-1"><div className="truncate text-[13px] font-bold text-[#3a4d54]">{item.title}</div><div className="mt-1 truncate text-[11px] text-[#87959a]">{item.sub}</div></div><div className="hidden text-right sm:block"><div className="text-[10px] font-bold text-[#53666d]">{item.due}</div><div className="mt-1 text-[10px] text-[#a0aaad]">esperando {item.waiting}</div></div><ChevronRight size={15} className="text-[#a6b2b5]" /></button>)}</div></Panel><div className="space-y-6"><Panel title="Próximo do prazo"><div className="p-5"><div className="flex items-start gap-3"><div className="flex h-9 w-9 items-center justify-center rounded-lg bg-[#fff3d9] text-[#b3791d]"><AlertCircle size={16} /></div><div><div className="text-[13px] font-bold text-[#3d5056]">Solicitação de contratação</div><div className="mt-1 text-[11px] text-[#8a989d]">Informação pendente de Fernanda Lima</div><div className="mt-3 flex items-center gap-1 text-[11px] font-semibold text-[#bb7b1e]"><Clock3 size={13} /> vence em 5h</div></div></div></div></Panel><Panel title="Atualizações recentes"><div className="space-y-4 p-5"><MiniUpdate initials="RC" tone="violet" text="Roberto aprovou a etapa de gestor" time="há 12 min" /><MiniUpdate initials="MC" tone="teal" text="Mariana comentou no parecer financeiro" time="há 28 min" /><MiniUpdate initials="FL" tone="orange" text="Fernanda adicionou um anexo" time="há 1h" /></div></Panel></div></div></>;
}

function InboxStat({ value, label, tone }: { value: string; label: string; tone: string }) { return <div className="rounded-2xl border border-[#e5edef] bg-white p-4 shadow-card"><div className={cn("font-display text-[24px] font-bold", tone === "teal" ? "text-[#16817d]" : tone === "amber" ? "text-[#b2791c]" : tone === "blue" ? "text-[#5e79aa]" : "text-[#52646b]")}>{value}</div><div className="mt-1 text-[10px] font-medium text-[#87959a]">{label}</div></div>; }
function MiniUpdate({ initials, tone, text, time }: { initials: string; tone: string; text: string; time: string }) { return <div className="flex items-center gap-3"><Avatar initials={initials} tone={tone} size="sm" /><div className="min-w-0 flex-1"><div className="text-[11px] leading-4 text-[#50636a]">{text}</div><div className="mt-0.5 text-[10px] text-[#a0abad]">{time}</div></div></div>; }

function ProcessesPage({ navigate }: { navigate: (href: string) => void }) {
  return <><PageHeader title="Processos" description="Acompanhe os fluxos que fazem a sua operação acontecer e encontre os gargalos." action={<Button variant="secondary"><Filter size={15} /> Filtrar processos</Button>} /><div className="mb-7 grid gap-4 sm:grid-cols-3"><StatCard label="Fluxos ativos" value="14" detail="3 novos este mês" icon={Workflow} tone="teal" /><StatCard label="Dentro do prazo" value="89%" detail="↑ 4% nos últimos 30 dias" icon={Gauge} tone="blue" /><StatCard label="Principal gargalo" value="Diretoria" detail="média de 19h de espera" icon={AlertCircle} tone="coral" /></div><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{processTemplates.map((process) => <button key={process.title} onClick={() => navigate("/analytics")} className="group rounded-2xl border border-[#e5edef] bg-white p-5 text-left shadow-card transition hover:-translate-y-0.5 hover:border-[#bddbd8]"><div className="flex items-start justify-between"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#eaf7f5] text-[#14807c]"><Workflow size={18} /></div><MoreHorizontal size={17} className="text-[#b0bbbe]" /></div><h3 className="mt-5 text-[14px] font-bold text-[#33474e]">{process.title}</h3><div className="mt-1 text-[11px] text-[#89979b]">{process.count} solicitações em andamento</div><div className="mt-5 grid grid-cols-3 gap-2 border-t border-[#edf1f1] pt-4"><div><div className="text-[10px] text-[#9aa7aa]">Tempo médio</div><div className="mt-1 text-[12px] font-bold text-[#4c5e64]">{process.avg}</div></div><div><div className="text-[10px] text-[#9aa7aa]">No prazo</div><div className="mt-1 text-[12px] font-bold text-[#4c5e64]">{process.sla}</div></div><div><div className="text-[10px] text-[#9aa7aa]">Gargalo</div><div className="mt-1 truncate text-[12px] font-bold text-[#c06954]">{process.bottleneck}</div></div></div></button>)}</div><Panel className="mt-6"><div className="flex flex-col gap-4 p-5 sm:flex-row sm:items-center sm:justify-between"><div className="flex items-center gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#fff3db] text-[#b37a1f]"><Sparkles size={18} /></div><div><div className="text-[13px] font-bold text-[#3b4f56]">Quer configurar um novo fluxo?</div><div className="mt-1 text-[11px] text-[#89979e]">Crie um modelo de processo para sua organização.</div></div></div><Button variant="secondary" onClick={() => navigate("/modelos")}>Ver modelos de processos <ArrowRight size={14} /></Button></div></Panel></>;
}

function AnalyticsPage() {
  return <><PageHeader title="Analytics" description="Entenda onde sua empresa está perdendo tempo." action={<Button variant="secondary"><CalendarDays size={15} /> Últimos 30 dias <ChevronDown size={13} /></Button>} /><div className="mb-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Tempo total médio" value="31h" detail="por processo concluído" icon={Clock3} tone="blue" /><StatCard label="Tempo efetivamente trabalhado" value="6h" detail="19% do tempo total" icon={Activity} tone="teal" /><StatCard label="Tempo esperando pessoas" value="25h" detail="81% do tempo total" icon={Clock3} tone="coral" emphasis /><StatCard label="SLA cumprido" value="89%" detail="↑ 4% no período" icon={Gauge} tone="amber" /></div><div className="grid gap-6 xl:grid-cols-[1.5fr_.8fr]"><Panel title="Tempo trabalhado × Tempo de espera" action={<div className="flex gap-3 text-[10px] text-[#839196]"><span className="flex items-center gap-1.5"><span className="h-2 w-2 rounded-full bg-[#1aa5a1]" /> Trabalhado</span><span className="flex items-center gap-1.5"><span className="h-2 w-2 rounded-full bg-[#d8e9e8]" /> Espera</span></div>}><div className="p-5"><div className="mb-6 flex items-end gap-7"><div><div className="font-display text-[34px] font-bold tracking-[-.05em] text-[#23373e]">31h</div><div className="text-[11px] text-[#87959a]">tempo total médio</div></div><div><div className="font-display text-[25px] font-bold tracking-[-.04em] text-[#16817d]">6h</div><div className="text-[11px] text-[#87959a]">trabalhado</div></div><div><div className="font-display text-[25px] font-bold tracking-[-.04em] text-[#b2c9c9]">25h</div><div className="text-[11px] text-[#87959a]">esperando</div></div></div><div className="relative h-[210px] border-b border-l border-[#e8eeee] pl-5"><div className="absolute inset-x-5 top-[25%] border-t border-dashed border-[#edf1f1]" /><div className="absolute inset-x-5 top-[50%] border-t border-dashed border-[#edf1f1]" /><div className="absolute inset-x-5 top-[75%] border-t border-dashed border-[#edf1f1]" /><div className="absolute bottom-0 left-8 right-5 flex h-[92%] items-end justify-around gap-4">{[["Compras", 78, 22], ["Contratos", 86, 14], ["Pagamentos", 67, 33], ["Contratação", 82, 18], ["Manutenção", 73, 27], ["Acessos", 63, 37]].map(([label, wait, work]) => <div className="flex h-full flex-1 flex-col items-center justify-end" key={label as string}><div className="flex h-full w-full max-w-[42px] flex-col justify-end overflow-hidden rounded-t-md bg-[#dceceb]"><div style={{ height: `${work}%` }} className="w-full bg-[#1aa5a1]" /></div><span className="mt-2 whitespace-nowrap text-[9px] text-[#91a0a4]">{label}</span></div>)}</div></div><div className="mt-5 rounded-xl bg-[#f1fbfa] p-4"><div className="flex items-start gap-3"><Sparkles size={16} className="mt-0.5 shrink-0 text-[#14817d]" /><div><div className="text-[13px] font-bold text-[#2c5658]">81% do tempo dos processos analisados é gasto esperando uma ação.</div><div className="mt-1 text-[11px] leading-5 text-[#6f8788]">A maior oportunidade está em reduzir o tempo entre etapas, não em pedir que as pessoas trabalhem mais rápido.</div></div></div></div></div></Panel><Panel title="Principais gargalos"><div className="p-5">{[["Aprovação da Diretoria", "19h", "coral"], ["Revisão Jurídica", "14h", "amber"], ["Aprovação Financeira", "8h", "teal"], ["Informações do solicitante", "5h", "blue"]].map(([label, value, tone], i) => <div key={label} className="flex items-center gap-3 border-b border-[#f0f3f3] py-4 first:pt-0 last:border-0 last:pb-0"><span className="flex h-6 w-6 items-center justify-center rounded-md bg-[#f4f7f7] text-[10px] font-bold text-[#87969b]">0{i + 1}</span><div className="min-w-0 flex-1"><div className="truncate text-[12px] font-semibold text-[#52646b]">{label}</div><div className="mt-1.5 h-1.5 overflow-hidden rounded-full bg-[#edf2f2]"><div className={cn("h-full rounded-full", tone === "coral" ? "bg-[#e8795f]" : tone === "amber" ? "bg-[#e8ad54]" : tone === "teal" ? "bg-[#1aa5a1]" : "bg-[#8aaadd]")} style={{ width: `${100 - i * 18}%` }} /></div></div><div className="text-right"><div className="text-[14px] font-bold text-[#3e5158]">{value}</div><div className="text-[10px] text-[#9ba7aa]">média</div></div></div>)}</div><div className="border-t border-[#edf1f1] px-5 py-3 text-[10px] leading-4 text-[#98a5a8]">Análise por etapa e processo. A JOEX não cria rankings de produtividade individual.</div></Panel></div><div className="mt-6 grid gap-4 md:grid-cols-2"><InsightCard title="O processo de análise de contratos está levando 32% mais tempo este mês." detail="A etapa de revisão jurídica concentra 54% do tempo de espera." /><InsightCard title="Solicitações com valor e centro de custo preenchidos concluem 1,4 dia mais rápido." detail="Pequenas melhorias na entrada evitam idas e vindas durante o fluxo." /></div></>;
}

function InsightCard({ title, detail }: { title: string; detail: string }) { return <div className="flex gap-3 rounded-2xl border border-[#e5edef] bg-white p-5 shadow-card"><div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-[#fff3db] text-[#b17b21]"><Sparkles size={15} /></div><div><div className="mb-1 text-[10px] font-bold uppercase tracking-[.1em] text-[#b17b21]">Insight JOEX</div><div className="text-[13px] font-bold leading-5 text-[#40535a]">{title}</div><div className="mt-2 text-[11px] leading-5 text-[#849398]">{detail}</div></div></div>; }

function TeamPage() {
  return <><PageHeader title="Equipe" description="Gerencie as pessoas, departamentos e funções que participam dos processos." action={<Button><Plus size={16} /> Adicionar pessoa</Button>} /><div className="mb-5 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div className="flex items-center gap-2"><Badge tone="teal">24 pessoas</Badge><Badge>6 departamentos</Badge></div><div className="flex h-10 w-full items-center gap-2 rounded-[10px] border border-[#e5edef] bg-white px-3 shadow-sm sm:w-64"><Search size={15} className="text-[#9aa8ac]" /><input placeholder="Buscar pessoa" className="min-w-0 flex-1 bg-transparent text-[12px] outline-none placeholder:text-[#a0adb1]" /></div></div><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{team.map((member) => <div key={member.name} className="rounded-2xl border border-[#e5edef] bg-white p-5 shadow-card"><div className="flex items-start justify-between"><div className="flex items-center gap-3"><Avatar initials={member.initials} tone={member.tone} size="lg" /><div><div className="text-[13px] font-bold text-[#354850]">{member.name}</div><div className="mt-1 text-[11px] text-[#89979d]">{member.role}</div></div></div><MoreHorizontal size={17} className="text-[#aeb9bc]" /></div><div className="mt-5 grid grid-cols-2 gap-3 border-t border-[#edf1f1] pt-4"><div><div className="text-[10px] text-[#9aa7aa]">Departamento</div><div className="mt-1 text-[11px] font-semibold text-[#54666d]">{member.department}</div></div><div><div className="text-[10px] text-[#9aa7aa]">Função na JOEX</div><div className="mt-1 text-[11px] font-semibold text-[#54666d]">{member.access}</div></div></div><div className="mt-4 flex items-center gap-1.5 text-[10px] font-semibold"><span className={cn("h-1.5 w-1.5 rounded-full", member.status === "Ativo" ? "bg-[#55aa6d]" : "bg-[#dba143]")} /><span className={member.status === "Ativo" ? "text-[#4a915e]" : "text-[#ad791e]"}>{member.status}</span></div></div>)}</div></>;
}

function TemplatesPage({ navigate }: { navigate: (href: string) => void }) {
  return <><PageHeader title="Modelos" description="Padronize documentos e processos para sua equipe começar mais rápido." action={<Button><Plus size={16} /> Criar modelo</Button>} /><div className="grid gap-6 xl:grid-cols-[1fr_1.05fr]"><Panel title="Modelos de documentos"><div className="grid gap-3 p-5 sm:grid-cols-2">{["Memorando", "Ofício", "Solicitação", "Parecer", "Relatório", "Comunicado", "Contrato", "Documento em branco"].map((name, i) => <button key={name} onClick={() => navigate("/documentos/editor")} className="flex items-center gap-3 rounded-xl border border-[#e7eeee] p-3 text-left hover:border-[#b9dbd8] hover:bg-[#fbfdfd]"><div className="flex h-8 w-8 items-center justify-center rounded-lg bg-[#eaf7f5] text-[#14807c]"><FileText size={15} /></div><span className="text-[12px] font-semibold text-[#52656b]">{name}</span><ChevronRight size={14} className="ml-auto text-[#b0bbbe]" /></button>)}</div></Panel><Panel title="Modelos de processos"><div className="p-5"><div className="mb-5 rounded-xl bg-[#f7faf9] p-4"><div className="text-[11px] font-bold text-[#51656a]">Aquisição de equipamentos</div><div className="mt-1 text-[10px] text-[#94a1a4]">Fluxo padrão · atualizado há 3 dias</div></div><div className="space-y-0">{["Solicitação", "Gestor", "Financeiro", "Diretoria", "Concluído"].map((step, i) => <div key={step} className="flex items-center gap-3"><div className="flex flex-col items-center"><div className={cn("flex h-8 w-8 items-center justify-center rounded-full border text-[11px] font-bold", i === 0 ? "border-[#9bd8d4] bg-[#e8f8f6] text-[#0d7b77]" : "border-[#dfe8e9] bg-white text-[#8c9b9f]")}>{i + 1}</div>{i < 4 && <div className="h-7 w-px bg-[#dce7e7]" />}</div><div className="flex flex-1 items-center justify-between"><span className="text-[12px] font-semibold text-[#51646a]">{step}</span>{i === 1 && <Badge tone="teal">Aprovação</Badge>}{i === 2 && <Badge tone="blue">Aprovação</Badge>}</div></div>)}</div><button className="mt-6 flex w-full items-center justify-center gap-2 rounded-lg border border-dashed border-[#b9d8d6] py-3 text-[11px] font-bold text-[#147d79] hover:bg-[#f2fbfa]"><Plus size={14} /> Adicionar etapa</button></div></Panel></div><Panel className="mt-6"><div className="p-5"><div className="mb-4 flex items-center gap-2"><Workflow size={16} className="text-[#14817c]" /><h2 className="font-display text-[15px] font-bold text-[#31454b]">Exemplo de fluxo paralelo</h2></div><div className="flex flex-col items-center gap-2 rounded-xl bg-[#fbfcfc] p-6 sm:flex-row sm:justify-center sm:gap-6"><div className="rounded-lg border border-[#dce8e8] bg-white px-5 py-3 text-[12px] font-semibold text-[#52666c] shadow-sm">Gestor</div><div className="hidden h-px w-8 bg-[#cbdada] sm:block" /><div className="space-y-3"><div className="rounded-lg border border-[#dce8e8] bg-white px-5 py-3 text-center text-[12px] font-semibold text-[#52666c] shadow-sm">Jurídico</div><div className="rounded-lg border border-[#dce8e8] bg-white px-5 py-3 text-center text-[12px] font-semibold text-[#52666c] shadow-sm">Financeiro</div></div><ArrowRight size={16} className="rotate-90 text-[#9daaae] sm:rotate-0" /><div className="rounded-lg border border-[#bfe0dd] bg-[#effafa] px-5 py-3 text-[12px] font-bold text-[#167b77] shadow-sm">Diretoria</div></div></div></Panel></>;
}

function AutomationsPage() {
  const rules = [["Quando uma solicitação ficar 24 horas sem ação", "Enviar lembrete", "Ativa", Clock3], ["Quando ultrapassar o prazo", "Avisar o gestor responsável", "Ativa", AlertCircle], ["Compras abaixo de R$ 500", "Aprovação automática do Financeiro", "Ativa", WandSparkles], ["Contratos acima de R$ 50.000", "Adicionar Diretoria ao fluxo", "Rascunho", ShieldCheck]] as const;
  return <><PageHeader title="Automações" description="Crie regras simples para manter os processos avançando sem acompanhamento manual." action={<Button><Plus size={16} /> Nova automação</Button>} /><div className="mb-7 rounded-2xl border border-[#cbe8e5] bg-[#effaf9] p-5"><div className="flex items-start gap-3"><div className="flex h-9 w-9 items-center justify-center rounded-lg bg-[#d8f2ef] text-[#0d7b77]"><WandSparkles size={17} /></div><div><div className="text-[13px] font-bold text-[#28595a]">Automatize o próximo passo</div><div className="mt-1 max-w-xl text-[11px] leading-5 text-[#648184]">As automações da JOEX ajudam a lembrar, encaminhar e manter cada processo em movimento. Você sempre poderá revisar o que foi feito.</div></div></div></div><div className="grid gap-4 md:grid-cols-2">{rules.map(([when, action, status, Icon]) => <div key={when} className="rounded-2xl border border-[#e5edef] bg-white p-5 shadow-card"><div className="flex items-start justify-between"><div className="flex h-9 w-9 items-center justify-center rounded-lg bg-[#f0f5f5] text-[#6d8187]"><Icon size={17} /></div><div className="flex items-center gap-2"><Badge tone={status === "Ativa" ? "green" : "neutral"}>{status}</Badge><MoreHorizontal size={16} className="text-[#aab5b8]" /></div></div><div className="mt-5"><div className="text-[10px] font-bold uppercase tracking-[.1em] text-[#9aa7aa]">Quando</div><div className="mt-1.5 text-[13px] font-bold text-[#3e5259]">{when}</div><div className="my-4 h-px bg-[#edf1f1]" /><div className="text-[10px] font-bold uppercase tracking-[.1em] text-[#9aa7aa]">Então</div><div className="mt-1.5 text-[13px] font-bold text-[#16807b]">{action}</div></div></div>)}</div></>;
}

function AdminPage() {
  return <><PageHeader title="Administração" description="Configure a organização, permissões, SLAs e preferências da JOEX." /><div className="grid gap-6 xl:grid-cols-[.85fr_1.15fr]"><Panel title="Configurações da organização"><div className="divide-y divide-[#edf1f1]">{[["Empresa Exemplo S.A.", "Dados da organização", BuildingIcon], ["Departamentos", "6 departamentos cadastrados", Users], ["Permissões", "Papéis e níveis de acesso", ShieldCheck], ["Notificações", "Preferências de avisos", Bell], ["Integrações", "Conecte outras ferramentas", Link2]].map(([name, desc, Icon]) => <button key={name as string} className="flex w-full items-center gap-3 px-5 py-4 text-left hover:bg-[#fbfdfd]"><div className="flex h-8 w-8 items-center justify-center rounded-lg bg-[#f0f5f5] text-[#72858a]"><Icon size={15} /></div><div className="flex-1"><div className="text-[12px] font-bold text-[#465960]">{name as string}</div><div className="mt-1 text-[10px] text-[#99a6aa]">{desc as string}</div></div><ChevronRight size={15} className="text-[#a9b4b7]" /></button>)}</div></Panel><Panel title="Padrões de processo"><div className="space-y-5 p-5"><label className="flex items-center justify-between gap-4"><span><span className="block text-[12px] font-bold text-[#4b5e65]">Prazo padrão de solicitações</span><span className="mt-1 block text-[10px] text-[#9aa7aa]">Usado quando não houver prazo específico</span></span><select className="rounded-lg border border-[#dfe8e9] px-3 py-2 text-[11px] text-[#62747a]"><option>3 dias úteis</option><option>5 dias úteis</option></select></label><label className="flex items-center justify-between gap-4"><span><span className="block text-[12px] font-bold text-[#4b5e65]">Lembrete automático</span><span className="mt-1 block text-[10px] text-[#9aa7aa]">Avisar após quanto tempo sem ação?</span></span><select className="rounded-lg border border-[#dfe8e9] px-3 py-2 text-[11px] text-[#62747a]"><option>24 horas</option><option>48 horas</option></select></label><label className="flex items-center justify-between gap-4"><span><span className="block text-[12px] font-bold text-[#4b5e65]">Exibir ETA nos processos</span><span className="mt-1 block text-[10px] text-[#9aa7aa]">Mostrar previsão de conclusão para a equipe</span></span><span className="relative h-6 w-11 rounded-full bg-[#1aa5a1]"><span className="absolute right-1 top-1 h-4 w-4 rounded-full bg-white shadow-sm" /></span></label></div></Panel></div></>;
}

function BuildingIcon(props: { size?: number }) { return <svg width={props.size || 16} height={props.size || 16} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><rect width="16" height="20" x="4" y="2" rx="2" /><path d="M9 22v-4h6v4M8 6h.01M12 6h.01M16 6h.01M8 10h.01M12 10h.01M16 10h.01M8 14h.01M12 14h.01M16 14h.01" /></svg>; }
